package com.example.erp.service;
import com.example.erp.dto.*; import com.example.erp.entity.PaymentCategory; import com.example.erp.exception.*; import com.example.erp.repository.PaymentCategoryRepository; import com.example.erp.security.OrganizationContext; import java.time.Instant; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentCategoryService { private final PaymentCategoryRepository repository; private final OrganizationContext context; public PaymentCategoryService(PaymentCategoryRepository repository,OrganizationContext context){this.repository=repository;this.context=context;}
 @Transactional(readOnly=true) public PageResponse<PaymentCategoryResponse> list(PageQuery q){var p=repository.findByOrganizationId(context.requiredOrganizationId(),PageRequest.of(q.page(),Math.min(q.size(),100),Sort.by(Sort.Direction.fromString(q.safeDirection()),q.sort())));return PageResponse.of(p.getContent().stream().map(PaymentCategoryResponse::from).toList(),p.getNumber(),p.getSize(),p.getTotalElements());}
 @Transactional public PaymentCategoryResponse create(PaymentCategoryRequest r){UUID org=context.requiredOrganizationId();String n=r.name().trim();if(repository.existsByOrganizationIdAndNameIgnoreCase(org,n))throw new BusinessRuleException("Payment category name already exists");return PaymentCategoryResponse.from(repository.save(new PaymentCategory(UUID.randomUUID(),org,n,Instant.now())));}
 @Transactional public PaymentCategoryResponse rename(UUID id,PaymentCategoryRequest r){UUID org=context.requiredOrganizationId();PaymentCategory c=repository.findByIdAndOrganizationId(id,org).orElseThrow(ResourceNotFoundException::new);String n=r.name().trim();if(!n.equalsIgnoreCase(c.getName())&&repository.existsByOrganizationIdAndNameIgnoreCase(org,n))throw new BusinessRuleException("Payment category name already exists");c.rename(n);return PaymentCategoryResponse.from(c);}
 @Transactional public void deactivate(UUID id){PaymentCategory c=repository.findByIdAndOrganizationId(id,context.requiredOrganizationId()).orElseThrow(ResourceNotFoundException::new);c.deactivate();}
}
